import {tools,icon} from './catalog-client.mjs';
import {cardHTML,href} from './catalog-view.mjs';
import {blogIndex,blogCard} from './blog.mjs';
const featured=['image-converter','qr-code','calculator','pdf-merge','background-remover','ielts-overall'];
const tasks=[['image','Edit an image','images'],['file','Work with PDFs','pdf'],['calculator','Calculate','calculators'],['type','Create something','creators'],['book','Study smarter','study'],['code','Build a project','developer']];
export const homeCard=cardHTML;
export function homeHTML(favorites=new Set()){
 return `<section class="directory-intro"><div class="directory-title"><h1>Free Tools</h1><span>${tools.length} useful shortcuts. One place.</span></div><form class="directory-search home-search" data-tool-search role="search" action="./tools/" method="get"><label class="sr-only" for="directory-query">Search free tools</label><div><span>${icon('search')}</span><input id="directory-query" name="q" type="search" placeholder="Search tools, calculators, or something you need to do…" autocomplete="off"><button class="btn primary" type="submit">Search</button></div></form><nav class="task-strip" aria-label="Browse by task"><strong>What do you want to do?</strong>${tasks.map(([symbol,label,id])=>`<a href="${href('category',id)}">${icon(symbol)}<span>${label}</span></a>`).join('')}</nav></section>
 <section class="directory-featured" aria-label="Popular free tools"><h2 class="sr-only">Popular free tools</h2><div class="tool-grid">${featured.map(id=>cardHTML(tools.find(t=>t.id===id),favorites)).join('')}</div><a class="all-tools-link" href="./tools/">Browse all ${tools.length} tools ${icon('arrow')}</a></section>
 <section class="directory-collections"><div class="section-head"><h2>Collections</h2><a href="./tools/">View all categories ${icon('arrow')}</a></div><div class="collection-row">${[['image','The image desk','Convert, compress, crop, and create.','images'],['receipt','Work without the busywork','Useful tools for documents and business.','business'],['book','A little progress, every day','Study, practice, and learn something new.','study']].map(([symbol,title,desc,id])=>`<a href="${href('category',id)}">${icon(symbol)}<div><h3>${title}</h3><p>${desc}</p></div>${icon('arrow')}</a>`).join('')}</div></section>
 <section class="recent-section" data-recent-section hidden><div class="section-head"><h2>Recently used</h2><button class="text-link" data-clear-recent>Clear history</button></div><div class="tool-grid" data-recent-grid></div></section>
 <section class="directory-guides"><div class="section-head"><h2>Good tools. A little know-how.</h2><a href="./blog/">Read all ${blogIndex.length} guides ${icon('arrow')}</a></div><div class="blog-grid">${[blogIndex[0],blogIndex[8],blogIndex[27]].map(blogCard).join('')}</div></section>
 <aside class="directory-resume">${icon('file')}<div><h2>Your next chapter starts with a good resume.</h2><p>Build a resume and cover letter in Nepocore Resume Studio.</p></div><a class="btn primary" href="https://resume.nepocore.com/">Open Resume Studio ${icon('arrow')}</a></aside>
 <div class="directory-promise"><span>${icon('check')} Free to use</span><span>${icon('lock')} No account required</span><a href="./privacy/">${icon('shield')} Your files stay in your browser</a></div>`;
}
